-- Temporal Magic and the circles: 89 spell rows three long-held books print and
-- the catalog never held.
--
-- One-off data script, run once per environment. NOT a migration - it adds
-- rows, not schema.
--
-- Rifts Book of Magic, printed 244-251: all 25 Temporal Magic spells, tradition
--   `temporal`, levels 7-15 from the list on printed 244. The book's first full
--   inventory (2026-10-03, in its survey) found no tradition held them, and the
--   Phase World Time Master has waited on these rows. Four are the same spell as
--   an untagged row the catalog already holds and carry same_spell_as, as a
--   tradition reprint does: Sense Dimensional Anomaly, Time Capsule, Wink-Out
--   and Dimensional Pockets (the book prints the plural). The list's
--   Temporary Time Hole is NOT the catalog's Time Hole and is not linked.
-- Palladium Fantasy RPG Main Book, printed 138-155: the Summoner's 51 circles -
--   18 protection, 15 summoning, 18 power - tradition `circle`. A circle prints
--   no level, so level is 0, as China 1's demonic curses are; each prints its
--   own P.P.E., which is stored. The Diabolist's wards are NOT here: a ward is
--   built from a sequence of symbols and is not one row.
-- Revised Heroes Unlimited, printed 104-106: 13 circles, tradition `circle`.
--   That book prints neither a level nor a P.P.E. cost for a circle, so both
--   are 0 with the fact in ppe_note.
--
-- EVERY NUMBER WAS READ OFF A RENDER and checked against a render again by
-- book-reconcile: 89 rows, no wrong level, cost or page. The counts are the
-- books' own: 25 on the Temporal list, and 18/15/18 on Palladium Fantasy's
-- list of circles on printed 137.
--
-- NO CLASS IS WIRED TO THESE ROWS HERE. Nothing grants the `temporal` or
-- `circle` tradition yet; the Summoner and the Time Master still describe their
-- magic in prose. The rows are the catalog half.
--
-- CONVENTIONS:
--   Names carry the tradition prefix, "Temporal: " and "Circle: ", as the
--     bone, nature and ocean traditions do. Four Heroes Unlimited protection
--     circles share a name with a Palladium Fantasy one and carry
--     " (Heroes Unlimited)", because spells.name is unique.
--   Components and power words have no column and are in the description. A
--     power word is transcribed letter for letter.
--   A book slip is stored as printed and named in the row: "are 44 to save",
--     "60 foot (19.3 m)", "ruby diamond", "Lietalon".
--   A protection or summoning circle that prints no range, duration or save of
--     its own takes its section's general rule (printed 138, 145).

INSERT OR IGNORE INTO spells (name, level, ppe, ppe_note, variant_note, source, source_book, system, range, duration, damage, saving_throw, area_of_effect, casting_time, description, same_spell_as, tradition, ppe_permanent) VALUES
('Temporal: D-Phase', 7, 20, NULL, NULL, 'import', 'Rifts Book of Magic p.244', 'rifts', 'Self only.', '15 seconds (one melee round) per level of experience.', NULL, 'Not applicable.', NULL, NULL, 'Warps dimensional reality so the caster can pass through solid matter such as doors and M.D.C. walls, at a quarter of his normal speed (reduced by 75%) and holding his breath the whole way. If concentration breaks, the air runs out or the spell ends while he is still inside something, he is thrown 3D6 feet back to his starting point, takes 2D6 Hit Points of damage and is dazed for 1D4 melees with a single attack and no combat bonuses.', NULL, 'temporal', NULL),
('Temporal: D-Shift Phantom', 7, 20, NULL, NULL, 'import', 'Rifts Book of Magic p.244', 'rifts', 'Self only.', '15 seconds (one melee round) per level of experience.', NULL, 'Not applicable.', NULL, NULL, 'The caster becomes a motionless, semitransparent phantom, much like a hologram, that nothing can touch or hurt. He still sees his surroundings but hears nothing, and while shifted he is unable to move, talk, use psionics or work magic.', NULL, 'temporal', NULL),
('Temporal: D-Shift Two Dimensions', 7, 25, NULL, NULL, 'import', 'Rifts Book of Magic p.244-245', 'rifts', 'Self only.', '15 seconds (one melee round) per level of experience.', NULL, 'Not applicable.', NULL, NULL, 'Flattens the caster and everything he carries into a two dimensional image at one-sixteenth of his weight, which sensors (thermo, heat, motion) miss and the eye rarely picks out (hide 85%); he can cling to a wall or floor or be slid under a door. He cannot move, speak or cast in this form, though psionics needing neither speech nor motion still work, and he stays open to attack: blows and explosions do half damage while he is braced on a surface, gas does half, swallowed or injected drugs do nothing, and wind can carry him off.', NULL, 'temporal', NULL),
('Temporal: Suspended Animation/Stasis Field', 7, 10, '10 on himself, 30 on someone else', NULL, 'import', 'Rifts Book of Magic p.245', 'rifts', 'Self or other by touch.', 'Varies; maximum 10 years per level of experience.', NULL, '+2 to save vs magic.', NULL, NULL, 'Places the caster, or a person he touches, in stasis for a chosen span, waking healthy and rested. A willing subject gets no save; an unwilling one has to be restrained and saves at +2. The sleeper wakes early if the caster ends the spell, if Negate Magic is used, or if an attack brings his S.D.C. down to 10 or less.', NULL, 'temporal', NULL),
('Temporal: T-Dep (Time Deprivation)', 7, 20, NULL, NULL, 'import', 'Rifts Book of Magic p.245', 'rifts', '90 feet (27.4 m).', 'One minute (4 melees) per level of the spell caster.', NULL, 'Standard.', NULL, NULL, 'Scrambles the victim''s sense of time: beyond day or night he cannot tell the hour, feels worn out as though far more time had gone by, misreads clocks and forgets anything due within the hour. He is -10% on skills, -60% on any skill that depends on timing (Demolitions, for one), -3 on initiative, -1 on strike, parry and dodge, loses one melee action and cannot take part in a coordinated attack.', NULL, 'temporal', NULL),
('Temporal: Time Warp: Send', 7, 25, NULL, NULL, 'import', 'Rifts Book of Magic p.245', 'rifts', 'Touch.', 'Instant.', NULL, 'Not applicable.', NULL, NULL, 'Throws one object, or one container of objects, forward in time; it vanishes and comes back in the very same spot. Limits: 10 lbs (4.5 kg) and at most 8 hours into the future for each level of the caster.', NULL, 'temporal', NULL),
('Temporal: Attune Object to Owner', 8, 30, NULL, NULL, 'import', 'Rifts Book of Magic p.245', 'rifts', 'Touch.', 'One year per level of experience or until dispelled by the one who performed the spell.', NULL, 'Not applicable.', NULL, NULL, 'Tunes an item to its owner''s biological energy signature so that nobody else can make it work, Telemechanics included; a rune sword, for instance, still cuts for a thief but none of its powers answer him. The caster must touch object and owner together while casting. The item afterwards reads as magical and shows its owner an aura shared by everything attuned to him.', NULL, 'temporal', NULL),
('Temporal: Retro-Viewing', 8, 30, NULL, NULL, 'import', 'Rifts Book of Magic p.245', 'rifts', 'Self only.', 'One minute per level of experience.', NULL, 'Not applicable.', NULL, NULL, 'Shows the caster alone a silent replay of what took place in one confined spot (a room, a vehicle, a small area). He can reach back one hour for each level of experience and picks which few minutes inside that window he watches.', NULL, 'temporal', NULL),
('Temporal: See Dimensional Anomaly', 8, 30, NULL, NULL, 'import', 'Rifts Book of Magic p.246', 'rifts', 'Self.', 'Two minutes per level of experience.', NULL, 'Not applicable.', NULL, NULL, 'Once he knows roughly where an anomaly lies, the caster can see it: dimensional envelopes and pockets, people changed into two or fourth dimensional beings, and the unseen essence of entities and alien intelligences all become visible. Time holes stay hidden.', NULL, 'temporal', NULL),
('Temporal: Sense Dimensional Anomaly', 8, 30, NULL, NULL, 'import', 'Rifts Book of Magic p.246', 'rifts', 'Self.', 'Two minutes per level of experience.', NULL, 'Not applicable.', NULL, NULL, 'The wizard feels disturbances in the space-time continuum and can often sense the general location of each. He senses dimensional Rifts opening or closing within 50 miles (80 km); time holes, ley line storms, mystic portals and dimensional teleportation within one mile (1.6 km); dimensional envelopes within 100 feet (30 m) and dimensional pockets within 10 feet (3 m). Inside a 100 foot (30 m) radius he also notices a teleport, wink-out or time warp taking place and the presence of astral beings, entities, alien intelligences and two or fourth dimensional beings, without being able to pinpoint them.', 'Sense Dimensional Anomaly', 'temporal', NULL),
('Temporal: Time Capsule', 8, 30, NULL, NULL, 'import', 'Rifts Book of Magic p.246', 'rifts', 'Touch.', 'Varies, up to 50 years per level of experience.', NULL, 'Not applicable.', NULL, NULL, 'Items sealed in any container that closes completely (crate, trunk, box, knapsack, bag) are lifted out of the normal time continuum and perfectly preserved, a year outside passing as one minute inside the capsule. The magic remains in effect only while the container stays unopened, and ends the instant it is opened. Up to 50 lbs (22.5 kg) per level can be stored, and only picked plants and non-living materials such as food, water, potions, books, clothing, weapons and machines; living creatures need suspended animation instead.', 'Time Capsule', 'temporal', NULL),
('Temporal: Wink-Out', 8, 20, '20 for one minute, then 10 more per additional minute; five minute maximum, costing 60', NULL, 'import', 'Rifts Book of Magic p.246', 'rifts', 'Self.', 'Varies.', NULL, 'Unwilling travelers can try to save; standard.', NULL, NULL, 'The spell caster enters a short-lived time hole that lies in another dimension, so to an observer he seems to disappear or teleport, and he reappears on the exact spot he left. Each minute winked out passes for him as one melee round of 15 seconds, time he can use to reload or draw weapons, prepare a spell, hide a small object, destroy an item or drink a potion, and during it no normal, mystical or psionic means can locate the character. Nothing can be left behind in the hole. From fifth level the caster can take two people he is touching along with him.', 'Wink-Out', 'temporal', NULL),
('Temporal: Remote Viewing', 9, 45, NULL, NULL, 'import', 'Rifts Book of Magic p.246', 'rifts', 'Self; distance of 10 miles (16 km) per level of experience.', 'One minute per level of experience.', NULL, 'Not applicable.', NULL, NULL, 'Lets the caster watch, without sound, what is going on right now around one particular person, object or place within range. He must know the target well (someone he has met for a few minutes, a room he has been in) and have a fair idea of where it currently is; the spell watches, it does not find.', NULL, 'temporal', NULL),
('Temporal: S-Dep (Sensory Deprivation)', 9, 50, NULL, NULL, 'import', 'Rifts Book of Magic p.246-247', 'rifts', '90 feet (27.4 m).', 'One melee (15 seconds) per level of the spell caster.', NULL, 'Standard.', NULL, NULL, 'Severs the victim from his own senses: touch and the sense of time are gone, sound is muffled, and he cannot judge distance, speed or his own strength, so he may be badly hurt without knowing. He is -10 to strike, parry and dodge, always acts last, is -5 to save vs illusionary magic and -50% on skills, keeps a single melee action and moves at one-third speed, and later recalls it all only as a haze. A psionic victim can use no power but Mind Block, yet no mind attack can reach him.', NULL, 'temporal', NULL),
('Temporal: Time Warp: Age', 9, 45, NULL, NULL, 'import', 'Rifts Book of Magic p.247', 'rifts', '100 feet (30.5 m).', 'One minute per level of experience.', NULL, '-2 to save.', NULL, NULL, 'Ages the victim for a while to the far end of his race''s lifespan (around 100 for a human). Physical attributes, melee actions and bonuses are halved and he is last on initiative; S.D.C. drops to zero, Hit Points are -10, an M.D.C. being loses half its M.D.C., and skills are -20%. Shaken, he tends to run or hide. Creatures of magic and supernatural beings are immune.', NULL, 'temporal', NULL),
('Temporal: Time Warp: Slow Motion', 9, 45, '45 for one minute, plus 10 for each additional minute (no limit)', NULL, 'import', 'Rifts Book of Magic p.247', 'rifts', 'Area effect; 30 feet (9.1 m) per level of experience.', 'One minute (4 melee rounds) plus.', NULL, 'None, unless a fellow Temporal being (standard).', NULL, NULL, 'Slows time for every creature in the area but the caster, though to them nothing seems changed. While it lasts he is +1 to strike, +3 to parry and dodge, +4 on initiative, +10 on speed, +10% on Computer Operation, Palming, Pick Locks and Pick Pocket, and gains one extra melee action.', NULL, 'temporal', NULL),
('Temporal: Dimensional Pockets', 10, 20, '20 for a temporary pocket, 140 for a long-term one', NULL, 'import', 'Rifts Book of Magic p.247', 'rifts', 'Self only.', 'Varies. Temporary pockets last up to one hour per level of the spell caster. Long-term pockets can exist for years; six months per level of experience.', NULL, 'Not applicable.', NULL, NULL, 'Creates a small, portable limbo dimension reached through a real pocket, bag, sack, purse or backpack, which the character selects as his focus of orientation; without a physical container the power cannot work. He can reach into the dimensional pocket to retrieve items placed there earlier, anything small enough to hold in one hand, to a total of about 30 lbs (13.6 kg). To anybody else the container appears ordinary and empty unless the investigating character can see dimensional anomalies. Wizards seldom keep more than one or two long-term pockets and a magic bag offered for sale rarely holds more than three years of life; such a bag retails from 90,000 to a million credits, of which the maker seldom gets more than 20%.', 'Dimensional Pocket', 'temporal', NULL),
('Temporal: Temporary Time Hole', 10, 100, NULL, NULL, 'import', 'Rifts Book of Magic p.247-248', 'rifts', '50 foot (15.2 m) radius.', '15 seconds (one melee round) per level of experience.', NULL, 'None.', NULL, NULL, 'Carries the caster and everybody within the radius, friend or foe with no choosing, into an empty time hole of bare ground and drifting cloud, usually to settle a fight away from bystanders. However long they stay, to the outside world they are gone for only 2D4 seconds. For the first two melee rounds the caster is limited to one spell per round at half speed and half combat bonuses. Those able to Dimensional Teleport, open a Rift or use Temporal Magic can leave early.', NULL, 'temporal', NULL),
('Temporal: Time Maelstrom', 10, 55, NULL, NULL, 'import', 'Rifts Book of Magic p.248', 'rifts', '100 feet (30.5 m).', 'Instant.', NULL, 'Not applicable.', NULL, NULL, 'Cast at another spell caster within six seconds of his starting any time-travel magic, it churns the time stream so that he arrives at a random moment, anything from 4D4 seconds to 1D4 days on, and perhaps as far as 1D6x100 yards from where he left (percentile tables on the page; 91-00 means no effect). He always comes out last on initiative and down one attack for one minute, short 4D6 P.P.E. and with 2D6 damage to Hit Points (M.D. for a Mega-Damage creature).', NULL, 'temporal', NULL),
('Temporal: Time Warp: Fast Forward', 10, 70, NULL, NULL, 'import', 'Rifts Book of Magic p.248-249', 'rifts', 'Self.', 'Varies.', NULL, 'Unwilling travelers can try to save; standard.', NULL, NULL, 'The caster skips ahead in time by seconds, minutes or hours, living through only three seconds himself and returning to the same fixed spot, which may have changed meanwhile; travel is forward only. From fifth level he can bring two people he is touching. Trying to cut the jump short or change its length calls for a roll on the Time Warp Distortion Table, with results running from one second to 24 hours elapsed.', NULL, 'temporal', NULL),
('Temporal: Time Barrier', 11, 100, NULL, NULL, 'import', 'Rifts Book of Magic p.249', 'rifts', '100 foot (30.5 m) radius around the spell caster per level of experience.', 'Three minutes per level of experience.', NULL, 'Not applicable.', NULL, NULL, 'Shuts the area to time travel: no time traveler can come or go and no time-warping spell (Send, Slow Motion, Fast Forward, Time Capsule and the like) works inside it. The caster sets the length in secret when casting, and after that not even he can lift it early.', NULL, 'temporal', NULL),
('Temporal: Dimensional Envelope', 12, 60, '60 for a temporary envelope, 380 for a long-term one', NULL, 'import', 'Rifts Book of Magic p.249', 'rifts', 'Self only.', 'Varies. Temporary envelopes last up to three hours per level of the spell caster. Long-term envelopes can exist for decades; 20 years per level of experience.', NULL, 'Not applicable.', NULL, NULL, 'Opens a closet-sized pocket of limbo, roughly 10x10x6 feet (3x3x1.8 m), behind an unseen door that only its maker and others versed in Temporal Magic or dimensions can find and use. Goods, or the caster himself, can be stowed inside (air for one or two people lasts about two hours) and time runs normally there. Sense Magic, Presence Sense, See Aura and most other detection miss both the envelope and its contents; a Shifter senses one within 50 feet (15.2 m) and can find it in 2D6 minutes at 30% +5% per level.', NULL, 'temporal', NULL),
('Temporal: Id Self', 13, 400, NULL, NULL, 'import', 'Rifts Book of Magic p.249-250', 'rifts', 'Self.', 'Varies.', NULL, 'Special.', NULL, NULL, 'Calls a counterpart of the caster out of a parallel dimension, one such id self for every five levels starting at fifth; tables on the page set how its alignment, level, age and attributes differ, and it needs 4D6 hours to recover from the shock. It may turn out an ally or a rival. Sending it home is certain during the first 48 hours and 5% less likely each week after, -10% if it resists and +20% if it wants to go, with three attempts allowed before it is stranded. The same id self can be called again later at 8% per level.', NULL, 'temporal', NULL),
('Temporal: Fourth Dimension Transformation', 14, 350, NULL, NULL, 'import', 'Rifts Book of Magic p.250-251', 'rifts', 'Self only.', 'One minute (four melee rounds) per level of experience.', NULL, 'Not applicable.', NULL, NULL, 'Remakes the caster as a four dimensional sub-being with 50 M.D.C. who takes half damage from everything, cannot be fooled by illusion or mind control, sees through walls and across every spectrum, and can slip out of the third dimension to roam unseen and intangible, stepping back in to act. He gains a set of psionic powers with 1200 I.S.P., always has initiative, three extra attacks, +4 to strike, +6 to parry, dodge and save vs magic, psionics, poison and drugs, +10 vs Horror Factor, and Teleport: Superior and the time warps at will. Afterwards he must roll on the permanent side effects table (01-15% no insanity) and, if spared, on the temporary one.', NULL, 'temporal', NULL),
('Temporal: Time Warp: Space & Time', 15, 800, NULL, NULL, 'import', 'Rifts Book of Magic p.251', 'rifts', 'Self.', 'Varies.', NULL, 'Unwilling travelers can try to save; standard.', NULL, NULL, 'Joins teleportation to Time Warp: Fast Forward, so the caster arrives both later and somewhere else; travel in time is forward only. From sixth level he can carry two people, or up to 1000 lbs (450 kg), that he is touching as he casts.', NULL, 'temporal', NULL);

INSERT OR IGNORE INTO spells (name, level, ppe, ppe_note, variant_note, source, source_book, system, range, duration, damage, saving_throw, area_of_effect, casting_time, description, same_spell_as, tradition, ppe_permanent) VALUES
('Circle: Protection Circle: Simple', 0, 35, NULL, NULL, 'import', 'Palladium Fantasy RPG Main Book p.138', 'palladium-fantasy', 'Only those within the circle''s radius.', 'Permanent until destroyed or deactivated by the circle maker.', NULL, NULL, NULL, 'Five minutes to draw with chalk', 'The most basic circle: everyone inside is +1 on every saving throw, but it bars nobody and anyone may walk in freely. Drawn in white chalk or in white or clear wax. Power words: Acba yin Lo-kum.', NULL, 'circle', NULL),
('Circle: Protection Circle: Superior', 0, 70, NULL, NULL, 'import', 'Palladium Fantasy RPG Main Book p.138-139', 'palladium-fantasy', 'Only those within the circle''s radius.', 'Permanent until destroyed or deactivated by the circle maker.', NULL, '16 or higher vs circle magic for a barred being to enter.', NULL, '15 to 20 minutes', 'A sealed, stronger form of the basic circle giving +3 on every saving throw; animated dead are kept out and only people the maker invites enter without a save. Its line is silver or quartz crystal, sealed by the maker''s blood. Power words: Acba yin Lo-kum yin Kym-Nark-Mar.', NULL, 'circle', NULL),
('Circle: Protection from Angels', 0, 90, NULL, NULL, 'import', 'Palladium Fantasy RPG Main Book p.139', 'palladium-fantasy', 'Only those within the circle''s radius.', 'Permanent until destroyed or deactivated by the circle maker.', NULL, '16 or higher vs circle magic for a barred being to enter.', NULL, '15 to 20 minutes', 'Bars ki-lin, wing tips, Spirits of Light and angels, which may not approach closer than 10 feet (3 m); those inside are +6 to save vs their magic and psionics. Any drawing substance, plus a lump of salt, a dish of water, a lit candle and an empty sealed jar. Power words: Erva yin Tao-bo.', NULL, 'circle', NULL),
('Circle: Protection from Deevils', 0, 70, NULL, NULL, 'import', 'Palladium Fantasy RPG Main Book p.139', 'palladium-fantasy', 'Only those within the circle''s radius.', 'Permanent until destroyed or deactivated by the circle maker.', NULL, '16 or higher vs circle magic for a barred being to enter.', NULL, '15 to 20 minutes', 'Bars the whole Deevil family of Hel along with the Dar''ota and Malignous. Lesser Deevils stay 10 feet (3 m) back, while greater ones can come to the rim and try to force entry; occupants are +5 to save vs deevil magic and psionics. Drawn in holy water or in blood from a priest of light. Power words: Acba yin keron.', NULL, 'circle', NULL),
('Circle: Protection from Demons', 0, 70, NULL, NULL, 'import', 'Palladium Fantasy RPG Main Book p.139', 'palladium-fantasy', 'Only those within the circle''s radius.', 'Permanent until destroyed or deactivated by the circle maker.', NULL, '16 or higher vs circle magic for a barred being to enter.', NULL, '15 to 20 minutes', 'Bars the Demon family and other natives of Hades, gargoyles, gurgoyles, gargoylites and dimensional ghouls among them. Lesser demons stay 10 feet (3 m) back, greater ones can come to the rim and try to force entry; occupants are +5 to save vs demon magic and psionics. Drawn in holy water or in blood from a priest of light. Power words: Acba yin Pein.', NULL, 'circle', NULL),
('Circle: Protection from True Elementals', 0, 100, NULL, NULL, 'import', 'Palladium Fantasy RPG Main Book p.139', 'palladium-fantasy', 'Only those within the circle''s radius.', 'Permanent until destroyed or deactivated by the circle maker.', NULL, '16 or higher vs circle magic for a barred being to enter.', NULL, '15 to 20 minutes', 'Bars elementals: lesser ones stay 10 feet (3 m) back, greater ones can reach the rim and try to enter, and occupants are +3 to save vs their elemental magic and psionics. Angels, elemental by nature but not true elementals, save at +4 against it and enter unharmed if they do. Any drawing substance, plus a pearl in a dish of water, a dish of salt, a lit candle, a ruby and a diamond. Power words: Acba Tharsis-mycn yin Ariel-Rapere-kyn yin Seraph-mytyn yin Cherubot-kyn.', NULL, 'circle', NULL),
('Circle: Protection from Elemental Forces', 0, 120, NULL, NULL, 'import', 'Palladium Fantasy RPG Main Book p.139', 'palladium-fantasy', 'Only those within the circle''s radius.', 'Permanent until destroyed or deactivated by the circle maker.', NULL, NULL, NULL, '15 to 20 minutes', 'Shelters occupants from natural and magical elemental forces alike: +3 on saves against any elemental magic, and on a failed save damage, duration and effects are halved. Wind, rain and extremes of temperature are felt at half strength, and lightning, hail, falling trees, floods, mud slides, avalanches and earthquakes cannot touch those inside. Any drawing substance; the essential components are sapphire, topaz, onyx and emeralds. Power words: Acba Lo-kum yin Tao-bo.', NULL, 'circle', NULL),
('Circle: Protection from Evil', 0, 70, NULL, NULL, 'import', 'Palladium Fantasy RPG Main Book p.139', 'palladium-fantasy', 'Only those within the circle''s radius.', 'Permanent until destroyed or deactivated by the circle maker.', NULL, '16 or higher vs circle magic for a barred being to enter.', NULL, 'About 5-10 minutes', 'A broad circle that keeps out anything of evil alignment, human or not (animals are not counted), unless it saves vs circle magic, which a being of 7th level or higher does at +2. Occupants are +3 to save vs the magic and psionics of evil beings. Any drawing substance, with either a lit pure-wax candle or a clear glass jar or vial of water. Power words: Acba yin Ya-blik.', NULL, 'circle', NULL),
('Circle: Protection from Faerie Folk', 0, 70, NULL, NULL, 'import', 'Palladium Fantasy RPG Main Book p.139', 'palladium-fantasy', 'Only those within the circle''s radius.', 'Permanent until destroyed or deactivated by the circle maker.', NULL, '16 or higher vs circle magic for a barred being to enter.', NULL, '15 to 20 minutes', 'Bars every member of the Faerie race, goblins, leprechauns, pucks, spriggans, nymphs, kinnie ger and kelpies included; occupants are +4 to save vs faerie magic and psionics. Drawn in salt, with a cross or a horseshoe tied in red ribbon set at the center. Power word: Ya-blik.', NULL, 'circle', NULL),
('Circle: Protection from Ghosts, Spirits & Entities', 0, 70, NULL, NULL, 'import', 'Palladium Fantasy RPG Main Book p.139', 'palladium-fantasy', 'Only those within the circle''s radius.', 'Permanent until destroyed or deactivated by the circle maker.', NULL, '16 or higher vs circle magic for a barred being to enter.', NULL, '15 to 20 minutes', 'Bars every ghost, spirit and entity, which covers nymphs, Will-o-the-Wisps, energy beings, astral beings and fragments of supernatural intelligences; occupants are +4 to save vs their magic and psionics. Drawn in green, with sweet incense burning. Power words: Erva yin acba yin agu.', NULL, 'circle', NULL),
('Circle: Protection from Good', 0, 70, NULL, NULL, 'import', 'Palladium Fantasy RPG Main Book p.140', 'palladium-fantasy', 'Only those within the circle''s radius.', 'Permanent until destroyed or deactivated by the circle maker.', NULL, '16 or higher vs circle magic for a barred being to enter.', NULL, 'About 5-10 minutes', 'The mirror of the circle against evil: nothing of good alignment, human or not (animals are not counted), may enter unless it saves vs circle magic, at +2 if 7th level or higher. Occupants are +3 to save vs the magic and psionics of good beings. Any drawing substance, with either a lit pure-wax candle or a clear glass jar or vial of water. Power words: Acba Tao-bo.', NULL, 'circle', NULL),
('Circle: Protection from the Jinn', 0, 90, NULL, NULL, 'import', 'Palladium Fantasy RPG Main Book p.140', 'palladium-fantasy', 'Only those within the circle''s radius.', 'Permanent until destroyed or deactivated by the circle maker.', NULL, '16 or higher vs circle magic for a barred being to enter.', NULL, '15 to 20 minutes', 'Bars the Jinn; occupants are +6 to save vs their magic and psionics. Any drawing substance, plus a pearl in a dish of water, a dish of salt, a ruby, a diamond and a lit oil lantern (the book prints "ruby diamond"). Power words: Pein yin Erva yin Ya-ahk-met.', NULL, 'circle', NULL),
('Circle: Protection from Magic (simple)', 0, 50, NULL, NULL, 'import', 'Palladium Fantasy RPG Main Book p.140', 'palladium-fantasy', 'Only those within the circle''s radius.', 'Permanent until destroyed or deactivated by the circle maker.', NULL, NULL, NULL, '15 to 20 minutes', 'Bars nothing, but occupants are +2 to save vs magic of every kind (spells, elemental magic, witchcraft, necromancy, circles, wards, rituals), dropping to +1 against a god, demon lord or alien intelligence. Any drawing substance. Power words: Kym-nark-mar yin acba.', NULL, 'circle', NULL),
('Circle: Protection from Magic (superior)', 0, 100, NULL, NULL, 'import', 'Palladium Fantasy RPG Main Book p.140', 'palladium-fantasy', 'Only those within the circle''s radius.', 'Permanent until destroyed or deactivated by the circle maker.', NULL, NULL, NULL, '15 to 20 minutes', 'Bars nothing, but occupants are +6 to save vs magic of every kind (spells, elemental magic, witchcraft, necromancy, circles, wards, rituals), dropping to +3 against a god, demon lord or alien intelligence. Drawn in gold and sealed with the maker''s blood. Power words: Acba yin kym-nark-mar yin acba.', NULL, 'circle', NULL),
('Circle: Protection from the Old Ones', 0, 120, NULL, NULL, 'import', 'Palladium Fantasy RPG Main Book p.140', 'palladium-fantasy', 'Only those within the circle''s radius.', 'Permanent until destroyed or deactivated by the circle maker.', NULL, '16 or higher vs circle magic for a barred being to enter.', NULL, '15 to 20 minutes', 'Bars Old Ones and alien intelligences whatever shape they wear; occupants are +5 to save vs their horror factor, insanity, possession, psionics and magic. Drawn in holy water or blessed ink with an angel-feather quill and sealed with the maker''s blood. Power words: Agu yin Tao-bo yin Kym-nark-mar.', NULL, 'circle', NULL),
('Circle: Protection from the Undead', 0, 70, NULL, NULL, 'import', 'Palladium Fantasy RPG Main Book p.140', 'palladium-fantasy', 'Only those within the circle''s radius.', 'Permanent until destroyed or deactivated by the circle maker.', NULL, '16 or higher vs circle magic for a barred being to enter.', NULL, '15 to 20 minutes', 'Bars vampires of every type and form, zombies, mummies, shamblers, yema, dybbuk-possessed corpses and any other undead. Occupants are +5 to save vs their magic and psionics and vs horror factor, and a vampire''s mind control and calling cannot reach them. Needs a silver cross and a garlic clove; any drawing substance (holy water, garlic, sawdust and silver are usual). Power words: Pein yin Erva.', NULL, 'circle', NULL),
('Circle: Protection from Witches', 0, 70, NULL, NULL, 'import', 'Palladium Fantasy RPG Main Book p.140', 'palladium-fantasy', 'Only those within the circle''s radius.', 'Permanent until destroyed or deactivated by the circle maker.', NULL, '16 or higher vs circle magic for a barred being to enter.', NULL, '15 to 20 minutes', 'Bars witches and their familiars; occupants are +6 to save vs magic or psionics from either, and +1 vs attacks by other demonic minions the witch commands. Made of salt, with three iron nails hammered into the center. Power words: Acba Keron yin Pein.', NULL, 'circle', NULL),
('Circle: Protection from Were-beasts', 0, 70, NULL, NULL, 'import', 'Palladium Fantasy RPG Main Book p.140', 'palladium-fantasy', 'Only those within the circle''s radius.', 'Permanent until destroyed or deactivated by the circle maker.', NULL, '16 or higher vs circle magic for a barred being to enter.', NULL, '15 to 20 minutes', 'Bars were-beasts; occupants get +5 on saves against horror factor and against the creatures'' magic and psionics. Drawn in silver and sprinkled with holy water. Power words as printed: Acba yin Lietalon yin Erva.', NULL, 'circle', NULL),
('Circle: Summon Angels', 0, 150, NULL, NULL, 'import', 'Palladium Fantasy RPG Main Book p.146', 'palladium-fantasy', 'Dimensional portal.', 'Permanent until destroyed or deactivated by the circle maker.', NULL, '16 or higher vs circle magic for the summoned being to enter the protected area.', NULL, '30 to 60 minutes', 'Summons an angel, Spirit of Light, Wing Tip or Ki-lin; inside the protected wedge the Summoner is +6 to save vs its magic and psionics. Drawn in gold, with a live butterfly as the sacrifice (a moth will not do). Power words: Acba yin Tao-bo.', NULL, 'circle', NULL),
('Circle: Summon Animal', 0, 60, '60 for an animal from the surrounding area, 100 to bring one in from another land', NULL, 'import', 'Palladium Fantasy RPG Main Book p.146', 'palladium-fantasy', '20 mile (32 km) radius or dimensional portal.', 'Permanent until destroyed or deactivated by the circle maker.', NULL, '16 or higher vs circle magic for the summoned being to enter the protected area.', NULL, '30 to 60 minutes', 'Summons any animal, which will not attack a Summoner who stays in the protected wedge. In the battle of wills wild predators save at -2, tame animals and non-predators at -4. Drawn in blood of the kind of animal wanted, with any living animal sacrificed. Power words: Acba yin Acba yin Agu.', NULL, 'circle', NULL),
('Circle: Summon Lesser Demon or Deevil', 0, 100, NULL, NULL, 'import', 'Palladium Fantasy RPG Main Book p.146', 'palladium-fantasy', 'Dimensional portal.', 'Permanent until destroyed or deactivated by the circle maker.', NULL, '16 or higher vs circle magic for the summoned being to enter the protected area.', NULL, '30 to 60 minutes', 'Summons any lesser being of the Demon or Deevil families of Hades and Hel, or a Dar''ota, Dimensional Ghoul or Malignous; inside the protected wedge the Summoner is +6 to save vs its magic and psionics. Drawn in goat''s blood, with a goat or sheep sacrificed. Power words: Pein yin keron.', NULL, 'circle', NULL),
('Circle: Summon Greater Demon or Deevil', 0, 250, NULL, NULL, 'import', 'Palladium Fantasy RPG Main Book p.146', 'palladium-fantasy', 'Dimensional portal.', 'Permanent until destroyed or deactivated by the circle maker.', NULL, '16 or higher vs circle magic for the summoned being to enter the protected area.', NULL, '30 to 60 minutes', 'Summons any greater demon or deevil; inside the protected wedge the Summoner is +4 to save vs its magic and psionics. Drawn in dove''s blood, with three doves sacrificed. Power words: Xy yin Pein yin keron.', NULL, 'circle', NULL),
('Circle: Summon True Elementals', 0, 100, NULL, NULL, 'import', 'Palladium Fantasy RPG Main Book p.146', 'palladium-fantasy', NULL, 'Permanent until destroyed or deactivated by the circle maker.', NULL, '16 or higher vs circle magic for the summoned being to enter the protected area.', NULL, '30 to 60 minutes', 'Summons an elemental (angels, though elemental in nature, do not answer it); inside the protected wedge the Summoner is +3 to save vs elemental magic and psionics. Drawn in charcoal with an emerald, onyx, ruby and sapphire for the four elements; the sacrifice is fruit, halved by a sword or crushed. Power words: Acba yin Lo-kum.', NULL, 'circle', NULL),
('Circle: Summon Elemental Forces', 0, 150, NULL, NULL, 'import', 'Palladium Fantasy RPG Main Book p.146', 'palladium-fantasy', '20 miles (32 km) maximum radius.', 'Permanent until destroyed or deactivated by the circle maker.', NULL, '16 or higher vs circle magic for the summoned being to enter the protected area.', NULL, '30 to 60 minutes', 'Calls up elemental forces matching wizard and warlock weather and element spells (winds, lightning, fire ball, fog, rain, storms, tornado, drought, earthquake and the rest of the printed list) at the maker''s level with twice the usual radius and duration. One can be cast each minute, and as many lasting ones as the maker has levels may run together if they do not conflict. Those in the protected wedge are +3 to save vs elemental magic, take half damage and half effect on a failure and are untouched by the forces summoned. Drawn in iron dust with emeralds, onyx, topaz and sapphire; a hawk is sacrificed. Power words: Ya-ahk-Met.', NULL, 'circle', NULL),
('Circle: Summon Faerie Folk', 0, 100, NULL, NULL, 'import', 'Palladium Fantasy RPG Main Book p.146', 'palladium-fantasy', '20 mile (32 km) radius or via dimensional portal.', 'Permanent until destroyed or deactivated by the circle maker.', NULL, '16 or higher vs circle magic for the summoned being to enter the protected area.', NULL, '30 to 60 minutes', 'Summons any of the Faerie race (goblins, brownies, leprechauns, pucks, nymphs, kelpies and the rest); those in the protected wedge are +4 to save vs faerie magic and psionics. Drawn in flower petals or honey, with a lamb sacrificed. Power words: Acba yin Lictalon.', NULL, 'circle', NULL);

INSERT OR IGNORE INTO spells (name, level, ppe, ppe_note, variant_note, source, source_book, system, range, duration, damage, saving_throw, area_of_effect, casting_time, description, same_spell_as, tradition, ppe_permanent) VALUES
('Circle: Summon Gargoyles & Sub-Demons', 0, 100, NULL, NULL, 'import', 'Palladium Fantasy RPG Main Book p.147', 'palladium-fantasy', '20 mile (32 km) radius or via dimensional portal.', 'Permanent until destroyed or deactivated by the circle maker.', NULL, '16 or higher vs circle magic for the summoned being to enter the protected area.', NULL, '30 to 60 minutes', 'Summons a member of the Gargoyle race or another sub-demon such as a bug bear, boogieman, Brodkil or worm of Taut; those in the protected wedge are +4 to save vs its magic and psionics. Drawn with or in mud, with a lizard sacrificed. Power words: Pein yin Ariel-Rapere-Kyn.', NULL, 'circle', NULL),
('Circle: Summon Ghosts & Entities', 0, 100, NULL, NULL, 'import', 'Palladium Fantasy RPG Main Book p.147', 'palladium-fantasy', 'Dimensional portal.', 'Permanent until destroyed or deactivated by the circle maker.', NULL, '16 or higher vs circle magic for the summoned being to enter the protected area.', NULL, '30 to 60 minutes', 'Summons ghosts, entities and ghostly nature spirits such as the Will-o-the-wisp and nymphs, but not astral or energy beings or fragments of alien intelligences, which need Summon Spirits. The save bonus for those in the protected wedge is printed as "44", an evident misprint for +4. Drawn in owl''s blood, with two toads sacrificed. Power words: Agu yin Netosa.', NULL, 'circle', NULL),
('Circle: Summon Insects', 0, 50, NULL, NULL, 'import', 'Palladium Fantasy RPG Main Book p.147', 'palladium-fantasy', '20 mile (32 km) radius or via dimensional portal.', 'Permanent until destroyed or deactivated by the circle maker.', NULL, '16 or higher vs circle magic for the summoned being to enter the protected area.', NULL, '30 to 60 minutes', 'Summons ordinary insects and arachnids, venomous or not: 1D4x10 small ones or 1D6 giant ones for each level of experience. They attack as a swarm and obey only simple orders; intelligent or supernatural insect beings are unaffected. Drawn with crushed insects of the general kind wanted, with a giant cave or timber spider sacrificed. Power words: Yablik Yin Acba.', NULL, 'circle', NULL),
('Circle: Summon the Jinn', 0, 250, NULL, NULL, 'import', 'Palladium Fantasy RPG Main Book p.147', 'palladium-fantasy', 'Dimensional portal.', 'Permanent until destroyed or deactivated by the circle maker.', NULL, '16 or higher vs circle magic for the summoned being to enter the protected area.', NULL, '30 to 60 minutes', 'Summons any type of Jinn, a greater demon; those in the protected wedge are +4 to save vs its magic and psionics. Drawn in black (ink, paint or charcoal as a rule), with four rats sacrificed. Power words: Pein yin Erva.', NULL, 'circle', NULL),
('Circle: Summon Pawn', 0, 50, '100 for uses 1 and 2 (summoning); 50 for use 3 (communication)', NULL, 'import', 'Palladium Fantasy RPG Main Book p.147', 'palladium-fantasy', 'Dimensional portal or 1000 mile (1600 km) radius per level of experience.', 'Permanent until destroyed or deactivated by the circle maker.', NULL, '16 or higher vs circle magic for the summoned being to enter the protected area.', NULL, '30 to 60 minutes', 'Works on a mortal humanoid, or a creature of magic such as faerie folk, whose true name is written in the circle or whose hair or body part and a fresh drop of blood are set in it. It can (1) summon him for a battle of wills to enslave him, player characters saving at +3; (2) bring him to talk for up to one hour, after which, or if he is attacked, he returns to where he was; or (3) send an existing pawn a one-sentence call that repeats until he answers and leaves him drawn to his master unless he saves. Drawn in silver, with a lamb sacrificed. Power words: Tarm-Kin-Toe.', NULL, 'circle', NULL),
('Circle: Summon Serpents', 0, 50, '50 for ordinary snakes; 100 for Worms of Taut, Eye Killers and sea serpents; 200 for a Serpent of the Wind or Kukulcan', NULL, 'import', 'Palladium Fantasy RPG Main Book p.147-148', 'palladium-fantasy', '20 mile (32 km) radius or dimensional portal.', 'Permanent until destroyed or deactivated by the circle maker.', NULL, '16 or higher vs circle magic for the summoned being to enter the protected area.', NULL, '30 to 60 minutes', 'Summons 4D6 ordinary snakes per level of experience, venomous or not, or serpentine creatures of magic: Worms of Taut, Eye Killers, sea serpents (near open water) and the dragons Serpent of the Wind and Kukulcan. Intelligent reptile or snake peoples are unaffected. Drawn in a snake''s blood or scales, with a poisonous snake sacrificed. Power words: Ya-blik, or Ya-blik yin Kym-Nark-Mar for the two dragons.', NULL, 'circle', NULL),
('Circle: Summon Spirits', 0, 200, NULL, NULL, 'import', 'Palladium Fantasy RPG Main Book p.148', 'palladium-fantasy', 'Dimensional portal.', 'Permanent until destroyed or deactivated by the circle maker.', NULL, '16 or higher vs circle magic for the summoned being to enter the protected area.', NULL, '30 to 60 minutes', 'Summons astral travelers and monsters in astral form, natives of the Dreamstream, energy beings and fragments of alien intelligences; those in the protected wedge are +3 to save vs their magic and psionics. Drawn in lamb''s blood, with a dead butterfly (or its wings) laid on the butterfly symbol and a ram sacrificed. Power words: Agu yin Erva.', NULL, 'circle', NULL),
('Circle: Summon the Undead', 0, 100, NULL, NULL, 'import', 'Palladium Fantasy RPG Main Book p.148', 'palladium-fantasy', 'Dimensional portal.', 'Permanent until destroyed or deactivated by the circle maker.', NULL, '16 or higher vs circle magic for the summoned being to enter the protected area.', NULL, '30 to 60 minutes', 'Summons a free-willed undead (any vampire, a dybbuk-possessed corpse and the like) but not servants such as zombies, mummies, shamblers or yema; each use carries a 1-20% chance of also drawing a fragment of a vampire intelligence. Those in the protected wedge are +4 to save vs the creature''s magic and psionics and vs horror factor and cannot be reached by vampiric mind control. Needs a silver cross and a garlic clove; any drawing substance. Power words: Netosa yin Erva.', NULL, 'circle', NULL),
('Circle: All Seeing - Power Circle', 0, 400, '400 to create; 100 to watch a different person or to resume after the components were removed', NULL, 'import', 'Palladium Fantasy RPG Main Book p.149', 'palladium-fantasy', 'Unlimited', 'Active as long as the candle burns and all components remain in place. Becomes dormant when the candle burns out or is extinguished', NULL, 'None', NULL, '30 to 60 minutes', 'Finds one person anywhere in the same dimension (or the astral plane) and shows him live, with sound, from a fixed side-on view in the smoke of a candle, even if he is invisible. The target is fixed by his true name, by a bodily token such as hair or blood, or by sacrificing a friend or relative of his. A new target takes a 10 minute ceremony; an anti-magic cloud, sanctum, sanctuary, superior magic protection circle, or circle of wonder or power leech hides him. Drawn in mandrake juice with symbols in eagle''s blood; first use needs 1/2 ounce of dragon bone dust. Power words: Lictalon yin Lictalon-acba.', NULL, 'circle', NULL),
('Circle: Animate (and control) Dead - Power Circle', 0, 200, NULL, NULL, 'import', 'Palladium Fantasy RPG Main Book p.149-150', 'palladium-fantasy', 'Affects all who bear the symbol of death.', 'Active as long as it is occupied by the circle maker; becomes dormant when he leaves.', NULL, 'None', NULL, '30 to 60 minutes', 'Raises every corpse or skeleton marked in fresh salamander blood with the death symbol, up to 150 per level, to carry out orders given from inside the circle, at any distance. Each has two attacks, speed 7, 1D6 damage unarmed and S.D.C. by size (50 small, 80 medium, 140 large, 200 giant); missiles do half damage and fire double, and they must be wholly destroyed. They stop if the maker cancels with Ya-ahk-met yin Seraph-mytyn or is killed inside the circle. Drawn in the blood of a vampire or other undead. Power words: Xy yin Lo-kum yin Netosa yin Erva.', NULL, 'circle', NULL),
('Circle: Command - Power Circle', 0, 200, NULL, NULL, 'import', 'Palladium Fantasy RPG Main Book p.150', 'palladium-fantasy', 'Can charm/command anybody within a 60 foot (19.3 m) radius of the circle. Once a victim falls under the power of the Summoner he can be given a command and sent away beyond the 60 feet (18.3 m) still under the mage''s control.', 'Duration of the magic is 1D4 minutes per victim, per level of the circle maker. Only one person can be affected per melee round time, but the circle remains empowered, once activated, until destroyed.', NULL, 'Standard, unless the circle maker knows the "true name" of his intended victim; in that instance the victim is -4 to save.', NULL, '30 to 60 minutes', 'Forces the Summoner''s will on a living creature, which will then turn on friends, give up secrets or guard him, though it cannot be driven to suicide. Made of lotus petals with symbols in vegetable oil. Power words: Kym-nark-mar.', NULL, 'circle', NULL),
('Circle: Death - Power Circle', 0, 300, NULL, NULL, 'import', 'Palladium Fantasy RPG Main Book p.150', 'palladium-fantasy', '40 foot (12.2 m) radius or miles.', '10 melees per level of the circle maker.', '1D4 per level (general), 1D6 per level (direct), 1D6 (long range)', 'Standard per each attack!', NULL, '30 to 60 minutes', 'Offers three attacks, one per melee round: 1D4 per level to anyone the maker knows is inside the radius; 1D6 per level to a single target in line of sight; or 1D6 to a victim up to 500 miles (800 km) off by stabbing a doll made with his true name, hair or nail clippings and a personal item. The distant victim sees his attacker each time. Lesser magic protection halves the long range damage and the superior one, protection from evil, the wonder and force circles and several wards and spells stop it. Drawn in snake venom with symbols in quicksilver. Power words: Tarm-kin-toe yin Tarm-kin-toe.', NULL, 'circle', NULL),
('Circle: Dimensional Rift - Power Circle', 0, 500, '500 to create; 50 to reopen the portal later', NULL, 'import', 'Palladium Fantasy RPG Main Book p.150-151', 'palladium-fantasy', 'Special', 'The Rift remains open for one melee round per level of experience and can be closed in an instant at the command of the Summoner. If the circle maker is killed, the dimensional portal remains open for the maximum duration.', NULL, 'None', NULL, '30 to 60 minutes', 'Tears a two-way gateway just outside the circle to any dimension the maker knows even slightly, and he alone can retarget it later. Linked through a Power Matrix to a summoning circle it draws 1D6 natives of that dimension per level. Only magic barriers seal it for a time, and a permanence ward holds it open forever. Drawn in the maker''s blood and bearing his true name, symbols in deevil or demon excrement, and a still-warm dragon''s heart is stabbed three times. Power words: Acba yin Lo-kum yin Kym-nark-mar.', NULL, 'circle', NULL),
('Circle: Domination/Control - Power Circle', 0, 200, NULL, NULL, 'import', 'Palladium Fantasy RPG Main Book p.151', 'palladium-fantasy', '40 foot (12.2 m) radius around the circle or a specific person.', 'Varies', NULL, 'Standard', NULL, '90 to 120 minutes', 'Three uses. Everyone in the radius who fails must obey simple orders, and those who save still suffer -1 on initiative and to strike, parry or dodge against him, and -10% on skills that oppose him. Or the maker rides one victim in line of sight like a puppet, splitting his own actions. Or, entranced, he fully possesses a victim brought to the circle, out to 1000 miles (1600 km) and for one day per level, at -3 initiative and -10 on skills; his own body suffers 1D6 a day after two days. Orders of suicide or against professed ethics allow a save at +3. Made of stretched cat entrails, symbols in gold, with the victim''s true name, hair and nails at the center. Power words: Pein yin Lictalon.', NULL, 'circle', NULL),
('Circle: Force - Power Circle', 0, 200, '200 to create; 100 more to reactivate', NULL, 'import', 'Palladium Fantasy RPG Main Book p.151', 'palladium-fantasy', 'Circle area only.', '15 minutes per level of the circle maker.', NULL, 'None', NULL, '30 to 60 minutes', 'Walls the circle (or every circle in a power matrix) in a force that no amount of damage breaks and that keeps out vapors, lightning, fire balls, elementals, ghosts, entities and astral travelers; psionics, charms, mesmerism and illusion still get through. Dispel magic barriers drops it only for 1D4 melees, and the circle saves at +3 against that spell. After a full-duration use it must rest one hour. Any drawing substance; a white dove is sacrificed during the power words. Power words: Ya-ahk-met yin Ya-ahk-met.', NULL, 'circle', NULL),
('Circle: Healing - Power Circle', 0, 200, '200 to create, then 75 per activation', NULL, 'import', 'Palladium Fantasy RPG Main Book p.151', 'palladium-fantasy', 'Those in the top quarter of the circle area only.', 'Effects are permanent; healing properties of the circle last six melees per level of the circle maker per activation.', NULL, 'None', NULL, '30 to 60 minutes', 'Heals whoever stands in it, the maker included, at 4D6 hit points a melee round without scars, with a single 15% chance to lift a curse, +10% to save vs coma and +3 on saves against insanity, disease and poison. Drawn in silver with symbols in powdered butterfly wings. Power words: Acba yin Tao-bo yin Agu.', NULL, 'circle', NULL),
('Circle: Invisibility - Power Circle', 0, 200, NULL, NULL, 'import', 'Palladium Fantasy RPG Main Book p.152', 'palladium-fantasy', 'The people and objects within the circle.', 'Indefinitely while in the circle, 10 minutes per level of the circle maker once the character(s) leaves the confines of the circle. Same as the Invisibility Simple spell.', NULL, 'Standard', NULL, '30 to 60 minutes', 'Anyone who steps in turns invisible, stays so while inside and for the printed time after leaving, and cannot switch it off; for that reason this circle can never be sealed. From its bottom quarter the maker alone sees the invisible. It works until the toad skeleton is taken away. Drawn in powdered toad bone with symbols in clear wax, with a whole toad skeleton inside. Power words: Acba yin Cherubot-kyn.', NULL, 'circle', NULL),
('Circle: Insanity - Power Circle', 0, 300, NULL, NULL, 'import', 'Palladium Fantasy RPG Main Book p.152', 'palladium-fantasy', 'Circle radius', 'Indefinitely', NULL, 'Standard', NULL, '30 to 60 minutes', 'Assaults the mind of anyone entering or crossing it, up to 20 feet (6 m) overhead: a victim rolls on the random insanity tables once per minute spent inside. People whose true names are written in it are immune, and it works until washed away. Drawn with crushed scorpions, symbols in any paint or ink, and two live scorpions bound to a post at the center. Power words: Keron yin Lictalon.', NULL, 'circle', NULL),
('Circle: Knowledge - Power Circle', 0, 250, '250 to create, then 50 each time a tongue is burnt', NULL, 'import', 'Palladium Fantasy RPG Main Book p.152', 'palladium-fantasy', 'Circle radius.', 'Abilities last indefinitely while the Summoner and/or others allowed in the circle remain in the circle, but lasts 10 minutes per level of the circle maker upon leaving the circle.', NULL, 'None', NULL, '30 to 60 minutes', 'Burning a tongue on the brazier grants knowledge by its kind. Owl: +10% on skills, literacy in every tongue the user speaks and, inside the circle, all languages. Goblin: a 6th level thief''s O.C.C. and rogue skills. Wolfen: a 6th level ranger''s O.C.C. and wilderness skills. Wizard: that wizard''s knowledge at 6th level. Dragon: all languages spoken and written, holistic medicine and every lore at 10th level, with +20% on own skills. Painted yellow with blue symbols. Power words: Lictalon yin Kym-nark-mar-Agu.', NULL, 'circle', NULL),
('Circle: Pain - Power Circle', 0, 200, NULL, NULL, 'import', 'Palladium Fantasy RPG Main Book p.152', 'palladium-fantasy', 'Special', 'As long as the victim remains in the circle and the Summoner desires to inflict pain. Upon being released from the circle, the mage can continue to inflict pain through the doll effigy for five minutes per level of experience.', '1D4 per melee', 'Standard', NULL, '90 to 120 minutes', 'Torments only a person whose true name is written in it, through a straw or cloth doll bearing his hair, nail clippings or a belonging: each pin does just 1D4 damage a melee but hurts as if five times worse, and a save each round reduces it to a twinge with no damage. Drawn with crushed spiders, symbols in black. Power words: Netosa yin Tarm-kin-toe.', NULL, 'circle', NULL),
('Circle: Passion - Power Circle', 0, 200, NULL, NULL, 'import', 'Palladium Fantasy RPG Main Book p.152', 'palladium-fantasy', 'Special', 'Indefinitely as long as inside the circle, or for periods of 10 minutes per level of the circle maker on victims outside the circle.', NULL, 'Standard', NULL, '90 to 120 minutes', 'Fills the one person named in it with a chosen emotion (love, lust, hate, jealousy, anger) through a doll carrying his hair, nails or a belonging, dusted with mistletoe and hung over a flame, out to 100 miles (160 km) per level. A victim who fails is overwhelmed and likely to act at once; the maker cannot see how. Made of lotus petals, symbols in blue; a goat is sacrificed as the chant begins. Power words: Pein yin acba-Seraph-mytyn yin Lictalon.', NULL, 'circle', NULL),
('Circle: Power - Power Circle', 0, 400, '400 to create and empower the first time; 100 for each later use (typically 2-5 people plus the Summoner)', NULL, 'import', 'Palladium Fantasy RPG Main Book p.153', 'palladium-fantasy', 'Empowers those inside the circle with spell casting abilities; range as per magic spell.', 'Indefinitely while the character(s) remains in the circle. Upon leaving the circle, the spell casting abilities remain for one minute per level of the circle maker.', NULL, 'Standard', NULL, '90 to 120 minutes', 'Occupants standing in the directed-power quarter gain +5 on all saves, +2 spell strength if already casters, 1D6 bio-regeneration a round, and call lightning, wall of fire, resist fire and ball of flame at 1D6 per maker level, two spells a round inside and one a round after leaving, with the circle supplying the P.P.E. The maker also gets about a dozen more spells, among them charm, mesmerism, animate and turn dead, tongues and metamorphosis, and keeps two a round outside. Made while wearing a cockatrice or kukulcan skull helm marked with the force symbol, and drawn using an elf bone. Power words: Xy yin Lo-kum-yin Kym-nark-mark.', NULL, 'circle', NULL),
('Circle: Power Leech - Power Circle', 0, 300, NULL, NULL, 'import', 'Palladium Fantasy RPG Main Book p.153', 'palladium-fantasy', '30 foot (9 m) radius per level of the circle maker.', 'The circle is active and in effect only as long as it is occupied by somebody who knows how to use and direct its magic.', NULL, '-2 to save vs circle magic.', NULL, '30 to 60 minutes', 'Halves the strength, power and duration of spells, wards, other circles and the gifts of witches and clerics inside its reach, so a 6th level caster works at third, and swallows any energy thrown at it. A creature of magic or supernatural being forced inside also has combat abilities, bonuses, hit points and S.D.C. halved. Made of crushed leeches round a light, with two live leeches on each of the maker''s arms: one dropping off (1-30% each hour) ends the magic for 24 hours, and one torn off sets off an implosion of 2D4x10 inside the circle and 1D4x10 across its radius. Needs the dragon skull helm. Power words: Ya-ahk-met yin Lictalon.', NULL, 'circle', NULL),
('Circle: Power Matrix - Power Circle', 0, 500, '500 to create and use; 100 to reactivate and energize the connected circles', NULL, 'import', 'Palladium Fantasy RPG Main Book p.153', 'palladium-fantasy', 'Special', 'The magic is active only as long as it is occupied by somebody who knows how to use its magic.', NULL, 'None', NULL, 'Six hours, plus the creation of each linked circle', 'The one way to join 2, 3 or 4 circles so their maker can work them all from the matrix core without walking between them. Losing a linked circle removes only that circle; losing the matrix unlinks the rest, which still work alone. A star symbol of unbridled power carries six further symbols at its points, all in real gold; the dragon helm is worn and the eleven power words of forces are painted on the maker''s skin. Power words: Acba yin Xy yin Xy yin Ya-ahk-met yin Lo-kum.', NULL, 'circle', NULL),
('Circle: Teleport - Power Circle', 0, 300, '300 to create; later uses need no P.P.E., only the faerie wings', NULL, 'import', 'Palladium Fantasy RPG Main Book p.153-155', 'palladium-fantasy', 'Circle area/distance of 1800 miles.', 'Instant transportation.', NULL, 'None', NULL, '30 to 60 minutes', 'Sends everyone in it to the destination chalked inside when the power words are spoken and a pair of faerie wings is burnt, which takes one melee round; even someone who did not make the circle can use it this way. Normal teleport risks apply at +10% to success, and travel between two teleport circles, the other one named in silver or gold, never fails. Any drawing substance. Power words: Acba yin Lo-kum yin Cherubot-kyn.', NULL, 'circle', NULL);

INSERT OR IGNORE INTO spells (name, level, ppe, ppe_note, variant_note, source, source_book, system, range, duration, damage, saving_throw, area_of_effect, casting_time, description, same_spell_as, tradition, ppe_permanent) VALUES
('Circle: Wonder - Power Circle', 0, 300, NULL, NULL, 'import', 'Palladium Fantasy RPG Main Book p.155', 'palladium-fantasy', 'Special', 'The magic remains in effect the entire time that the unicorn horn burns.', NULL, 'Standard', NULL, '30 to 60 minutes', 'For everyone inside: remove curse 93%, 2D6 hit points or S.D.C. healed each round, exorcism 96% in 30 seconds, resurrection 89% in 60 seconds, and +8 on saves against curses, insanity, disease, poison, fear and horror factor; lesser deevils and demons, entities, scarecrows, golems, zombies, mummies and animated dead are held 30 feet (9 m) away (-3 to save). The maker can spread a weaker version 60 feet (18.3 m) out: 1D6 healing a round and +2 on those saves and vs possession. It also shields against the all seeing, death and passion circles and all summoning circles. Any drawing substance; a whole unicorn horn soaked in oil is burnt, lasting 6D6 minutes. Power words: Tao-bo yin acba yin Agu.', NULL, 'circle', NULL),
('Circle: Simple Circle of Protection', 0, 0, 'The Revised core states no level and no P.P.E. cost for a circle.', NULL, 'import', 'Revised Heroes Unlimited p.104', 'heroes-unlimited', 'Only those within the circle''s radius.', 'Permanent until destroyed.', NULL, '16 or higher to enter a protection circle.', NULL, '3 to 20 minutes', 'The basic circle, shown only in a diagram: it gives +1 on every saving throw. Left open, anyone may step in; sealed with three drops of the maker''s blood, only those he invites may, and others must save vs circles to force their way through an unseen barrier.', NULL, 'circle', NULL),
('Circle: Protection from Demonic Creatures (other-dimensional)', 0, 0, 'The Revised core states no level and no P.P.E. cost for a circle.', NULL, 'import', 'Revised Heroes Unlimited p.104', 'heroes-unlimited', 'Only those within the circle''s radius.', 'Permanent until destroyed.', NULL, '16 or higher to enter a protection circle.', NULL, '3 to 20 minutes', 'Demonic beings are shut out, and occupants are +3 to save against any attack from demonic forces. Drawn with holy water. Power words: Acba yin Pein.', NULL, 'circle', NULL),
('Circle: Protection from Elemental Forces (Heroes Unlimited)', 0, 0, 'The Revised core states no level and no P.P.E. cost for a circle.', NULL, 'import', 'Revised Heroes Unlimited p.104', 'heroes-unlimited', 'Only those within the circle''s radius.', 'Permanent until destroyed.', NULL, NULL, NULL, '3 to 20 minutes', 'Elemental forces of every kind, natural or magical, do only half damage to those inside. Any drawing substance, with emeralds, onyx, topaz and sapphire. Power words: Acba Lo-kum yin Tao-bo.', NULL, 'circle', NULL),
('Circle: Protection from Magic (simple) (Heroes Unlimited)', 0, 0, 'The Revised core states no level and no P.P.E. cost for a circle.', NULL, 'import', 'Revised Heroes Unlimited p.104', 'heroes-unlimited', 'Only those within the circle''s radius.', 'Permanent until destroyed.', NULL, NULL, NULL, '3 to 20 minutes', 'Occupants are +2 to save vs every magic attack, which here covers spells, circles, wards and psionics. Any drawing substance. Power words: Kym-nark-mar yin acba.', NULL, 'circle', NULL),
('Circle: Protection from Magic (superior) (Heroes Unlimited)', 0, 0, 'The Revised core states no level and no P.P.E. cost for a circle.', NULL, 'import', 'Revised Heroes Unlimited p.104', 'heroes-unlimited', 'Only those within the circle''s radius.', 'Permanent until destroyed.', NULL, NULL, NULL, '3 to 20 minutes', 'Occupants are +6 to save vs every magic attack. The circle has to be sealed with its maker''s blood. Power words: Acba yin kym-nark-mar yin acba.', NULL, 'circle', NULL),
('Circle: Protection from the Undead (Heroes Unlimited)', 0, 0, 'The Revised core states no level and no P.P.E. cost for a circle.', NULL, 'import', 'Revised Heroes Unlimited p.104', 'heroes-unlimited', 'Only those within the circle''s radius.', 'Permanent until destroyed.', NULL, '16 or higher to enter a protection circle.', NULL, '3 to 20 minutes', 'The undead are shut out of the circle. Needs a silver cross and a garlic clove; any drawing substance. Power words: Pein yin Erva.', NULL, 'circle', NULL),
('Circle: Force: Power Circle', 0, 0, 'The Revised core states no level and no P.P.E. cost for a circle.', NULL, 'import', 'Revised Heroes Unlimited p.104', 'heroes-unlimited', 'Circle area only', '15 melees per level of the circle maker.', NULL, 'None', NULL, 'About 60 minutes; reactivating takes 4 to 12 minutes', 'Walls the circle (or every circle in a power matrix) in a force that no amount of damage breaks and that stenches and clouds cannot pass, though psionics, charms and mesmerism still work against it. Dispel magic barriers drops it only until it regenerates within six melees, and the circle saves at +3 against that spell. The power words bring it back at any time, except that after a full-duration use it must rest two hours. Bears the directed-power symbol, any drawing substance; a white dove is sacrificed during the power words. Power words: Ya-ahk-met yin Ya-ahk-met.', NULL, 'circle', NULL),
('Circle: Invisibility: Power Circle', 0, 0, 'The Revised core states no level and no P.P.E. cost for a circle.', NULL, 'import', 'Revised Heroes Unlimited p.104-105', 'heroes-unlimited', 'The objects within the circle.', 'Permanent; 10 minutes per level of circle maker.', NULL, 'Standard', NULL, 'About 60 minutes; reactivating takes 4 to 12 minutes', 'Whoever enters, the maker included, turns invisible for the printed time and cannot switch it off early. The circle goes on working until its toad skeleton is taken away. Bears the directed-power symbol; drawn in powdered toad bone with symbols in clear wax, and a whole toad skeleton placed inside vanishes when it activates. Power words: Acba yin Cherubot-kyn.', NULL, 'circle', NULL),
('Circle: Knowledge: Power Circle', 0, 0, 'The Revised core states no level and no P.P.E. cost for a circle.', NULL, 'import', 'Revised Heroes Unlimited p.105', 'heroes-unlimited', 'Circle Radius', '15 melees per level of the circle maker', NULL, 'None', NULL, 'About 60 minutes; reactivating takes 4 to 12 minutes', 'Burning an owl''s tongue on the brazier gives the maker and anyone else inside +10% on all skills and the ability to speak and understand every language. Bears the directed-power symbol; painted yellow with blue symbols around a small brazier of hot coals. Power words: Lictalon yin Kym-nark-mar-Agu.', NULL, 'circle', NULL),
('Circle: Pain: Power Circle', 0, 0, 'The Revised core states no level and no P.P.E. cost for a circle.', NULL, 'import', 'Revised Heroes Unlimited p.105', 'heroes-unlimited', 'Special', '6 melees per level of the circle maker', '1D4 hit points per melee', 'Standard', NULL, 'About 60 minutes; reactivating takes 4 to 12 minutes', 'Torments only a person whose true name is written in it, by way of a straw or cloth doll bearing his hair, nail clippings or a belonging: each melee of pins does 1D4 hit points, a save each melee cuts that to a twinge with no damage, and it cannot take him below 10 hit points. Bears the force symbol; drawn with crushed spiders, symbols in black, with the victim bound at its center. Power words: Netosa yin Tarm-kin-toe.', NULL, 'circle', NULL),
('Circle: Power: Power Circle', 0, 0, 'The Revised core states no level and no P.P.E. cost for a circle.', NULL, 'import', 'Revised Heroes Unlimited p.105', 'heroes-unlimited', 'The people within the circle, and projected power.', 'Active until circle maker leaves or cancels it.', NULL, 'Standard', NULL, 'About 60 minutes; reactivating takes 4 to 12 minutes', 'Occupants gain +5 on all saves, +2 spell strength, bio-regeneration of 1-6 a melee, and can throw ball of flame, call lightning and wall of fire for 1-6 per maker level. While active it also produces charm, charismatic aura, weightlessness and mesmerism (the last two reaching 20ft past the circle), animate/control dead and control the beasts (1-6 per maker level each) and metamorphosis for those inside, all as the spells of those names. Worked while wearing a tiger-skull helm marked with the force symbol; drawn in silver using a tiger bone. Power words: Xy yin Lo-kum-yin Kym-nark-mark.', NULL, 'circle', NULL),
('Circle: Power Leech: Power Circle', 0, 0, 'The Revised core states no level and no P.P.E. cost for a circle.', NULL, 'import', 'Revised Heroes Unlimited p.105', 'heroes-unlimited', '30ft radius per level of the circle maker', 'Active only while circle maker remains in the circle.', NULL, '-2 to save vs circle magic.', NULL, 'About 60 minutes; reactivating takes 4 to 12 minutes', 'Halves the strength, power and duration of spells, illusionary magic, other circles and non-physical super abilities (not psionics) inside its reach, so a sixth level mage casts as a third, and swallows energy aimed at it, laser fire included. Made of crushed leeches round a light, with two live leeches on each of the maker''s arms; if one falls off the circle is cancelled. It can be restarted with the tiger-skull helm and the power words even after the leeches have dried. Power words as printed: Ya-ank-met yin Lictalon.', NULL, 'circle', NULL),
('Circle: Summoning Circle', 0, 0, 'The Revised core states no level and no P.P.E. cost for a circle.', NULL, 'import', 'Revised Heroes Unlimited p.105-106', 'heroes-unlimited', NULL, NULL, NULL, NULL, NULL, '30 to 90 minutes', 'A flawlessly drawn circle with exact components, finished by a blood sacrifice, brings a random creature of magic into its open-V area 1D6 minutes later; the being is rolled on the Monstrous Mystic Villains tables and is nearly always evil and hostile, held off only by the maker''s wedge of protection. It can be questioned and bargained with and favors wicked schemes. The same circle sends it back only if it never stepped away and goes within 30 minutes; otherwise it takes an exorcism or destroying it.', NULL, 'circle', NULL);

